import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import { Eye, EyeOff, Mail, KeyRound, ArrowLeft, Check } from "lucide-react";

const LOGO_SRC = "data:image/png;base64,";

function GoogleIcon({ size = 18 }) {
  return (
    <svg width={size} height={size} viewBox="0 0 48 48">
      <path fill="#FFC107" d="M43.6 20.5H42V20H24v8h11.3c-1.6 4.6-6 8-11.3 8-6.6 0-12-5.4-12-12s5.4-12 12-12c3.1 0 5.8 1.1 8 3l6-6C34.5 5.1 29.6 3 24 3 12.4 3 3 12.4 3 24s9.4 21 21 21 21-9.4 21-21c0-1.2-.1-2.4-.4-3.5z"/>
      <path fill="#FF3D00" d="M6.3 14.7l6.6 4.8C14.6 15.6 18.9 13 24 13c3.1 0 5.8 1.1 8 3l6-6C34.5 5.1 29.6 3 24 3c-7.6 0-14.1 4.3-17.7 10.7z"/>
      <path fill="#4CAF50" d="M24 45c5.5 0 10.4-1.9 14.2-5.1l-6.6-5.4C29.6 36.1 26.9 37 24 37c-5.3 0-9.7-3.4-11.3-8.1l-6.6 5.1C9.8 40.6 16.4 45 24 45z"/>
      <path fill="#1976D2" d="M43.6 20.5H42V20H24v8h11.3c-.8 2.3-2.2 4.2-4.1 5.6l6.6 5.4C41.6 35.9 45 30.5 45 24c0-1.2-.1-2.4-.4-3.5z"/>
    </svg>
  );
}

const NAVY = "#0d2436";
const NAVY_LIGHT = "#123048";
const ACCENT_BLUE = "#2f7bf6";

function Divider() {
  return (
    <div style={{ display: "flex", alignItems: "center", gap: "10px", margin: "18px 0" }}>
      <div style={{ flex: 1, height: "1px", background: "#e3e7ec" }} />
      <span style={{ fontSize: "12px", color: "#9aa4b0" }}>yoki</span>
      <div style={{ flex: 1, height: "1px", background: "#e3e7ec" }} />
    </div>
  );
}

const inputWrap = {
  display: "flex",
  alignItems: "center",
  border: "1px solid #e3e7ec",
  borderRadius: "10px",
  padding: "10px 12px",
  marginBottom: "14px",
  gap: "8px",
};

const inputBase = {
  border: "none",
  outline: "none",
  fontSize: "14px",
  flex: 1,
  minWidth: 0,
  background: "transparent",
};

const labelStyle = {
  fontSize: "12px",
  color: "#8a94a1",
  marginBottom: "6px",
  display: "block",
};

const primaryBtn = {
  width: "100%",
  padding: "12px 0",
  borderRadius: "10px",
  border: "none",
  background: NAVY,
  color: "#fff",
  fontSize: "14px",
  fontWeight: 600,
  cursor: "pointer",
};

const googleBtn = {
  width: "100%",
  padding: "11px 0",
  borderRadius: "10px",
  border: "1px solid #e3e7ec",
  background: "#fff",
  color: "#333",
  fontSize: "14px",
  fontWeight: 600,
  cursor: "pointer",
  display: "flex",
  alignItems: "center",
  justifyContent: "center",
  gap: "10px",
};

export default function LoginApp() {
  const navigate = useNavigate();
  const [mode, setMode] = useState("login"); // login | register | forgotEmail | forgotCode | forgotDone

  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [showPassword, setShowPassword] = useState(false);
  const [connecting, setConnecting] = useState(false);

  const [regEmail, setRegEmail] = useState("");
  const [regPassword, setRegPassword] = useState("");
  const [showRegPassword, setShowRegPassword] = useState(false);
  const [rememberPassword, setRememberPassword] = useState(true);
  const [regConnecting, setRegConnecting] = useState(false);

  const [forgotEmail, setForgotEmail] = useState("");
  const [code, setCode] = useState("");
  const [sending, setSending] = useState(false);
  const [error, setError] = useState("");

  function handleLoginSubmit(e) {
    e.preventDefault();
    setError("");
    if (!email.trim() || !email.includes("@")) {
      setError("Email manzilini to‘g‘ri kiriting");
      return;
    }
    if (!password.trim()) {
      setError("Parolni kiriting");
      return;
    }
    localStorage.setItem("isAuthenticated", "true");
    navigate("/", { replace: true });
  }

  function handleGoogleLogin() {
    setError("");
    setConnecting(true);
    setTimeout(() => {
      setConnecting(false);
      localStorage.setItem("isAuthenticated", "true");
      navigate("/", { replace: true });
    }, 900);
  }

  function handleForgotEmailSubmit(e) {
    e.preventDefault();
    if (!forgotEmail.trim() || !forgotEmail.includes("@")) {
      setError("Google akkaunt (email) manzilini to‘g‘ri kiriting");
      return;
    }
    setError("");
    setSending(true);
    setTimeout(() => {
      setSending(false);
      setMode("forgotCode");
    }, 900);
  }

  function handleCodeSubmit(e) {
    e.preventDefault();
    if (code.trim().length < 4) {
      setError("6 xonali kodni kiriting");
      return;
    }
    setError("");
    setMode("forgotDone");
  }

  function handleRegisterSubmit(e) {
    e.preventDefault();
    if (!regEmail.trim() || !regEmail.includes("@")) {
      setError("Email manzilini to‘g‘ri kiriting");
      return;
    }
    if (!regPassword.trim() || regPassword.length < 6) {
      setError("Parol kamida 6 ta belgidan iborat bo‘lishi kerak");
      return;
    }
    setError("");
    alert("Ro‘yhatdan o‘tish (demo) — real backend ulanmagan.");
  }

  function handleGoogleRegister() {
    setError("");
    setRegConnecting(true);
    setTimeout(() => {
      setRegConnecting(false);
      alert("Google orqali ro‘yhatdan o‘tish (demo) — Google OAuth oynasi shu yerda ochiladi.");
    }, 900);
  }

  function switchMode(next) {
    setMode(next);
    setError("");
  }

  return (
    <div className="login-page">
      <style>{`
        .login-page {
          width: 100%;
          min-height: 100vh;
          display: grid;
          grid-template-columns: 1fr 1fr;
          background: #f4f6f8;
          font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
        }
        .login-left {
          background: linear-gradient(180deg, ${NAVY} 0%, ${NAVY_LIGHT} 100%);
          border-right: 3px solid ${ACCENT_BLUE};
          display: flex;
          flex-direction: column;
          align-items: center;
          justify-content: flex-start;
          padding: 48px 32px;
          color: #fff;
        }
        .login-left img.brand-logo {
          width: 200px;
          height: auto;
          filter: drop-shadow(0 10px 24px rgba(0,0,0,0.35));
        }
        .login-left h1 {
          font-size: 26px;
        }
        .login-right {
          display: flex;
          align-items: center;
          justify-content: center;
          padding: 32px;
        }
        .login-card {
          width: 100%;
          max-width: 360px;
          background: #fff;
          border-radius: 16px;
          box-shadow: 0 10px 40px rgba(15, 35, 60, 0.10);
          padding: 32px 28px;
        }

        @media (max-width: 768px) {
          .login-page {
            grid-template-columns: 1fr;
            min-height: auto;
          }
          .login-left {
            border-right: none;
            border-bottom: 3px solid ${ACCENT_BLUE};
            padding: 32px 20px 28px;
          }
          .login-left img.brand-logo {
            width: 140px;
          }
          .login-left h1 {
            font-size: 22px;
            margin-bottom: 18px !important;
          }
          .login-right {
            padding: 24px 16px 40px;
          }
        }

        @media (max-width: 380px) {
          .login-card {
            padding: 24px 18px;
          }
        }
      `}</style>

      {/* LEFT PANEL */}
      <div className="login-left">
        <div
          style={{
            width: "100%",
            display: "flex",
            justifyContent: "center",
            marginTop: "24px",
            marginBottom: "36px",
          }}
        >
          <img src={LOGO_SRC} alt="Logo" className="brand-logo" />
        </div>

        <h1
          style={{
            fontWeight: 700,
            marginBottom: "24px",
            textAlign: "center",
          }}
        >
          {mode === "register" ? "Ro‘yhatdan o‘tish" : "Tizimga kirish"}
        </h1>

        <div
          style={{
            display: "flex",
            background: "rgba(255,255,255,0.08)",
            borderRadius: "999px",
            padding: "4px",
            gap: "4px",
          }}
        >
          <button
            onClick={() => switchMode("login")}
            style={{
              padding: "10px 22px",
              borderRadius: "999px",
              border: "none",
              cursor: "pointer",
              fontSize: "14px",
              fontWeight: 600,
              background:
                mode === "login" || mode.startsWith("forgot")
                  ? "#fff"
                  : "transparent",
              color:
                mode === "login" || mode.startsWith("forgot") ? NAVY : "#cfd8e3",
              transition: "all 0.2s ease",
            }}
          >
            Kirish
          </button>
          <button
            onClick={() => switchMode("register")}
            style={{
              padding: "10px 22px",
              borderRadius: "999px",
              border: "none",
              cursor: "pointer",
              fontSize: "14px",
              fontWeight: 600,
              background: mode === "register" ? "#fff" : "transparent",
              color: mode === "register" ? NAVY : "#cfd8e3",
              transition: "all 0.2s ease",
            }}
          >
            Ro‘yhatdan o‘tish
          </button>
        </div>

        <p
          style={{
            marginTop: "auto",
            paddingTop: "48px",
            fontSize: "12px",
            color: "rgba(255,255,255,0.45)",
            textAlign: "center",
          }}
        >
          Hujjatlaringizni tez va oson formatga o‘girish tizimi
        </p>
      </div>

      {/* RIGHT PANEL */}
      <div className="login-right">
        <div className="login-card">
          <div
            style={{
              display: "flex",
              justifyContent: "center",
              marginBottom: "22px",
            }}
          >
            <img src={LOGO_SRC} alt="Logo" style={{ width: "72px", height: "auto" }} />
          </div>

          {error && (
            <div
              style={{
                background: "#fdecec",
                color: "#c0392b",
                fontSize: "13px",
                padding: "10px 12px",
                borderRadius: "8px",
                marginBottom: "16px",
                textAlign: "center",
              }}
            >
              {error}
            </div>
          )}

          {/* ---------- LOGIN ---------- */}
          {mode === "login" && (
            <>
              <form onSubmit={handleLoginSubmit}>
                <label style={labelStyle}>Email</label>
                <div style={inputWrap}>
                  <Mail size={16} color="#9aa4b0" />
                  <input
                    type="email"
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                    placeholder="ism@example.com"
                    style={inputBase}
                  />
                </div>

                <label style={labelStyle}>Parol</label>
                <div style={inputWrap}>
                  <input
                    type={showPassword ? "text" : "password"}
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    placeholder="Parolingizni kiriting"
                    style={inputBase}
                  />
                  <button
                    type="button"
                    onClick={() => setShowPassword((v) => !v)}
                    style={{ background: "none", border: "none", cursor: "pointer", display: "flex" }}
                  >
                    {showPassword ? <EyeOff size={16} color="#9aa4b0" /> : <Eye size={16} color="#9aa4b0" />}
                  </button>
                </div>

                <button type="submit" style={{ ...primaryBtn, marginTop: "4px" }}>
                  Tizimga kirish
                </button>
              </form>

              <Divider />

              <button type="button" onClick={handleGoogleLogin} disabled={connecting} style={{ ...googleBtn, opacity: connecting ? 0.7 : 1 }}>
                <GoogleIcon />
                {connecting ? "Ulanmoqda..." : "Google orqali kirish"}
              </button>

              <p style={{ textAlign: "center", marginTop: "18px" }}>
                <button
                  type="button"
                  onClick={() => switchMode("forgotEmail")}
                  style={{ background: "none", border: "none", color: ACCENT_BLUE, fontSize: "13px", cursor: "pointer" }}
                >
                  Men parolni unutdim
                </button>
              </p>
            </>
          )}

          {/* ---------- FORGOT: ASK GOOGLE ACCOUNT ---------- */}
          {mode === "forgotEmail" && (
            <form onSubmit={handleForgotEmailSubmit}>
              <button
                type="button"
                onClick={() => switchMode("login")}
                style={{ background: "none", border: "none", color: "#5b6773", fontSize: "13px", cursor: "pointer", display: "flex", alignItems: "center", gap: "4px", marginBottom: "14px" }}
              >
                <ArrowLeft size={14} /> Orqaga
              </button>

              <p style={{ fontSize: "13px", color: "#5b6773", marginBottom: "16px" }}>
                Parolni tiklash uchun ro‘yhatdan o‘tgan Google akkauntingizni kiriting.
                Tasdiqlash kodi shu emailga yuboriladi.
              </p>

              <label style={labelStyle}>Google akkaunt</label>
              <div style={{ ...inputWrap, marginBottom: "18px" }}>
                <Mail size={16} color="#9aa4b0" />
                <input
                  type="email"
                  value={forgotEmail}
                  onChange={(e) => setForgotEmail(e.target.value)}
                  placeholder="ism@gmail.com"
                  style={inputBase}
                />
              </div>

              <button type="submit" disabled={sending} style={{ ...primaryBtn, cursor: sending ? "default" : "pointer", opacity: sending ? 0.7 : 1 }}>
                {sending ? "Yuborilmoqda..." : "Kod yuborish"}
              </button>
            </form>
          )}

          {/* ---------- FORGOT: ENTER CODE ---------- */}
          {mode === "forgotCode" && (
            <form onSubmit={handleCodeSubmit}>
              <button
                type="button"
                onClick={() => switchMode("forgotEmail")}
                style={{ background: "none", border: "none", color: "#5b6773", fontSize: "13px", cursor: "pointer", display: "flex", alignItems: "center", gap: "4px", marginBottom: "14px" }}
              >
                <ArrowLeft size={14} /> Orqaga
              </button>

              <p style={{ fontSize: "13px", color: "#5b6773", marginBottom: "16px" }}>
                <strong>{forgotEmail}</strong> manziliga 6 xonali tasdiqlash kodi yuborildi.
              </p>

              <label style={labelStyle}>Tasdiqlash kodi</label>
              <div style={{ ...inputWrap, marginBottom: "18px" }}>
                <KeyRound size={16} color="#9aa4b0" />
                <input
                  value={code}
                  onChange={(e) => setCode(e.target.value)}
                  placeholder="- - - - - -"
                  maxLength={6}
                  style={{ ...inputBase, fontSize: "16px", letterSpacing: "4px" }}
                />
              </div>

              <button type="submit" style={primaryBtn}>
                Tasdiqlash
              </button>
            </form>
          )}

          {/* ---------- FORGOT: DONE ---------- */}
          {mode === "forgotDone" && (
            <div style={{ textAlign: "center", padding: "12px 0" }}>
              <div style={{ width: "56px", height: "56px", borderRadius: "50%", background: "#e7f7ec", display: "flex", alignItems: "center", justifyContent: "center", margin: "0 auto 16px" }}>
                <Check size={28} color="#2e9e56" />
              </div>
              <p style={{ fontSize: "14px", color: "#333", marginBottom: "20px" }}>
                Kod tasdiqlandi. Endi yangi parol o‘rnatishingiz mumkin.
              </p>
              <button onClick={() => switchMode("login")} style={primaryBtn}>
                Kirishga qaytish
              </button>
            </div>
          )}

          {/* ---------- REGISTER ---------- */}
          {mode === "register" && (
            <>
              <form onSubmit={handleRegisterSubmit}>
                <label style={labelStyle}>Email</label>
                <div style={inputWrap}>
                  <Mail size={16} color="#9aa4b0" />
                  <input
                    type="email"
                    value={regEmail}
                    onChange={(e) => setRegEmail(e.target.value)}
                    placeholder="ism@example.com"
                    style={inputBase}
                  />
                </div>

                <label style={labelStyle}>Parol</label>
                <div style={inputWrap}>
                  <input
                    type={showRegPassword ? "text" : "password"}
                    value={regPassword}
                    onChange={(e) => setRegPassword(e.target.value)}
                    placeholder="Kamida 6 ta belgi"
                    style={inputBase}
                  />
                  <button
                    type="button"
                    onClick={() => setShowRegPassword((v) => !v)}
                    style={{ background: "none", border: "none", cursor: "pointer", display: "flex" }}
                  >
                    {showRegPassword ? <EyeOff size={16} color="#9aa4b0" /> : <Eye size={16} color="#9aa4b0" />}
                  </button>
                </div>

                <label style={{ display: "flex", alignItems: "center", gap: "8px", fontSize: "13px", color: "#5b6773", marginBottom: "18px", cursor: "pointer" }}>
                  <input
                    type="checkbox"
                    checked={rememberPassword}
                    onChange={(e) => setRememberPassword(e.target.checked)}
                    style={{ width: "15px", height: "15px" }}
                  />
                  Parolni eslab qolish
                </label>

                <button type="submit" style={primaryBtn}>
                  Ro‘yhatdan o‘tish
                </button>
              </form>

              <Divider />

              <button type="button" onClick={handleGoogleRegister} disabled={regConnecting} style={{ ...googleBtn, opacity: regConnecting ? 0.7 : 1 }}>
                <GoogleIcon />
                {regConnecting ? "Ulanmoqda..." : "Google orqali ro‘yhatdan o‘tish"}
              </button>
            </>
          )}
        </div>
      </div>
    </div>
  );
}
